<?php declare(strict_types=1); require __DIR__ . '/config.php'; header('Content-Type: application/xml; charset=utf-8'); $services = require __DIR__ . '/data/services.php'; $destinations = require __DIR__ . '/data/destinations.php'; echo '<?xml version="1.0" encoding="UTF-8"?>'; ?>
